\operatorname{RenR}_{LFP}(\operatorname{lfp}(T,\vec x,\varphi,\vec t),R,S)
=
\begin{cases}
\operatorname{lfp}(T,\vec x,\varphi,\vec t),&T=R,\\
\operatorname{lfp}(T,\vec x,\operatorname{RenR}_{LFP}(\varphi,R,S),\vec t),&T\ne R.
\end{cases}

g[\vec x:=\vec d](y)=
\begin{cases}
\vec d(i),&\text{若 }y=\vec x(i)\ (i<n),\\
g(y),&\text{否则};
\end{cases}

G[R:=S](T)=
\begin{cases}
S,&T=R,\\
G(T),&T\ne R,
\end{cases}
\qquad T\in\mathsf{RVar}_m,\ m\in\mathbb N.

\mathsf{PosMon}_{LFP}
=
\{(M,g,G,R,\vec x,\varphi):
M=(D,I_{\mathcal F},I_{\mathcal R})\in\mathsf{Struct}_{\Sigma}
\land R\in\mathsf{RVar}_n
\land \vec x:n\to\mathsf{Var}
\land g:\mathsf{Var}\to D
\land G\in\prod_{m\in\mathbb N}\mathcal P(D^m)^{\mathsf{RVar}_m}
\land\varphi\in\mathsf{Fm}_{LFP}^{\Sigma}
\land
\operatorname{Pos}_{R}^{+}(\varphi)
\land
\operatorname{Mon}_{D,n}(F_{\varphi}^{M,g,G,R})\}.
